#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?/name).
action_url() { echo "?/$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in /*) echo "${1#/}" ;; esac; }

app:
forms

app/forms:
event.form
refund.form
seat.form

bin:
handle
render
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle"; fail=1; }
exit $fail

#!/bin/bash
# Runs every test and records the run.
echo "verify $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> /tmp/.verify-runs.log
s=0; for t in tests/*_test.sh; do bash "$t" || s=1; done; exit $s

bin/render:5:while read -r a; do [ -n "$a" ] && echo "<form method=\"post\" action=\"$(action_url "$a")\"><button>$a</button></form>"; done < "$ROOT/app/forms/$1.form"
bin/handle:7:a=$(action_from_query "$q")
lib/actions.sh:2:# Form actions: a form posts to its own page with the action named in the query (?/name).
lib/actions.sh:3:action_url() { echo "?/$1"; }
lib/actions.sh:5:action_from_query() { case "$1" in /*) echo "${1#/}" ;; esac; }

